package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;import io.knowledgebrain.contracts.integration.githubwork.v1.*;
class GitHubWorkActivityTest extends ActivityFixtures {
 @Test void bothKindsKeepPrivateScopeAndStableSourceWithoutLearningAttribution(){for(String kind:List.of("GITHUB_ISSUE","GITHUB_PULL_REQUEST")){var raw=wire(kind,id());var e=ActivityEvent.decode(ActivityEvent.TOPICS.get(kind),raw);assertEquals("integration",ActivityEvent.group(kind));assertTrue(GitHubWorkActivity.target(e));assertNull(e.roadmapId());assertNull(e.nodeId());assertEquals("OPEN",e.state());assertTrue(e.detail().contains("자동 완료"));ActivityEvent.transport(ActivityEvent.TOPICS.get(kind),raw,e.aggregateId().toString(),headers(e));var p=ActivityQueryTest.params("kind",kind);var q=ActivityQuery.parse(e.spaceId(),p);p.put("before",new String[]{q.cursor(e)});assertThrows(RuntimeException.class,()->ActivityQuery.parse(id(),p));}}
 @Test void malformedIdentityPrivacyUrlStateVersionAndDraftCannotProject()throws Exception{var e=RoadmapEventEnvelopeV1.parseFrom(wire("GITHUB_PULL_REQUEST",id()));var p=GitHubWorkItemObservedV1.parseFrom(e.getPayload());for(var bad:List.of(p.toBuilder().setVisibility("PUBLIC"),p.toBuilder().setSourceVisibility("PRIVATE"),p.toBuilder().setKind("ISSUE"),p.toBuilder().setItemId(id().toString()),p.toBuilder().setUrl("https://evil.test/"),p.toBuilder().setVersion(2),p.toBuilder().clearDraft(),p.toBuilder().setState("MERGED"),p.toBuilder().setObservedAt("2020-01-01T00:00:00Z"))){assertThrows(RuntimeException.class,()->ActivityEvent.decode("integration.github-pull-request.v1",e.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}}
}
